// Generated by AI (UnitTest MCP)
//
// The board read ADRs from the working tree, so the design record it showed was
// whatever the open checkout happened to hold. Measured across 84 worktrees on
// 2026-07-30: 75 ADRs on origin/main, 65 worktrees missing between 1 and 26 of
// them, and the checkout this extension reads holding 49 of 75 with no error.
//
// These tests spawn real git repositories. The timeout is set on the suite for
// the reason adr-guard.test.mjs already records: the slow part is git, which
// every case uses, so a per-test timeout is one the next test added forgets.
import { execFileSync } from "node:child_process";
import { mkdirSync, mkdtempSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";

import { afterEach, describe, expect, it } from "vitest";

import { readAdrsOnRef } from "./adrRecord";

const directories: string[] = [];
const scratch = (prefix: string) => {
  const dir = mkdtempSync(join(tmpdir(), prefix));
  directories.push(dir);
  return dir;
};
afterEach(() => {
  for (const dir of directories.splice(0)) rmSync(dir, { recursive: true, force: true });
});

const git = (repo: string, args: string[]) =>
  execFileSync("git", args, { cwd: repo, encoding: "utf8", stdio: "pipe" });

const writeAdrs = (root: string, adrs: Record<string, string>) => {
  rmSync(join(root, "docs", "adr"), { recursive: true, force: true });
  mkdirSync(join(root, "docs", "adr"), { recursive: true });
  for (const [name, body] of Object.entries(adrs)) {
    writeFileSync(join(root, "docs", "adr", name), body);
  }
};

/** A clone whose `main` holds `onMain` but whose checkout holds `onBranch`. */
const cloneWhereTheCheckoutIsBehind = (
  onMain: Record<string, string>,
  onBranch: Record<string, string>
) => {
  const origin = scratch("adrrec-origin-");
  git(origin, ["init", "--quiet", "--initial-branch=main"]);
  git(origin, ["config", "user.email", "t@example.com"]);
  git(origin, ["config", "user.name", "T"]);
  writeAdrs(origin, onMain);
  git(origin, ["add", "-A"]);
  git(origin, ["commit", "--quiet", "-m", "record"]);

  const clone = scratch("adrrec-clone-");
  git(clone, ["clone", "--quiet", origin, "."]);
  git(clone, ["config", "user.email", "t@example.com"]);
  git(clone, ["config", "user.name", "T"]);
  git(clone, ["checkout", "--quiet", "-b", "feature"]);
  writeAdrs(clone, onBranch);
  git(clone, ["add", "-A"]);
  git(clone, ["commit", "--quiet", "-m", "behind"]);
  return clone;
};

const adr = (n: string, title: string, status: string) =>
  `# ADR-${n}: ${title}\n\n- Status: ${status}\n`;

const GIT_TEST_TIMEOUT_MS = 60_000;

describe(
  "readAdrsOnRef",
  () => {
    it("returns the record on main, not the checkout's subset", async () => {
      const repo = cloneWhereTheCheckoutIsBehind(
        {
          "0001-first.md": adr("0001", "First", "Accepted"),
          "0002-second.md": adr("0002", "Second", "Proposed"),
          "0003-third.md": adr("0003", "Third", "Accepted"),
        },
        { "0001-first.md": adr("0001", "First", "Accepted") }
      );

      const blobs = await readAdrsOnRef(repo);

      expect(blobs?.map((b) => b.path)).toEqual([
        "docs/adr/0001-first.md",
        "docs/adr/0002-second.md",
        "docs/adr/0003-third.md",
      ]);
      expect(blobs?.[1].text).toContain("Status: Proposed");
    });

    /// git frames each object as `<sha> <type> <size>\n<size bytes>\n`, and the
    /// size is in BYTES. Splitting the stream as text makes one multi-byte
    /// character shift every record after it, so the failure is silent
    /// corruption of later ADRs rather than an error on the one that caused it.
    it("reads content by byte length, so a multi-byte character cannot shift the stream", async () => {
      const repo = cloneWhereTheCheckoutIsBehind(
        {
          "0001-em-dash.md": `# ADR-0001: Decay — it is the point\n\n- Status: Accepted\n`,
          "0002-after.md": adr("0002", "Reads correctly regardless", "Proposed"),
        },
        {}
      );

      const blobs = await readAdrsOnRef(repo);

      expect(blobs?.[0].text).toContain("Decay — it is the point");
      expect(blobs?.[1].text).toContain("# ADR-0002: Reads correctly regardless");
      expect(blobs?.[1].text).toContain("Status: Proposed");
    });

    /// A fresh clone with no remote is a real state, and the caller has to be
    /// able to tell "no record here" from "an empty record".
    it("returns null when the ref cannot be resolved, rather than an empty record", async () => {
      const repo = scratch("adrrec-noremote-");
      git(repo, ["init", "--quiet", "--initial-branch=main"]);
      writeAdrs(repo, { "0007-local.md": adr("0007", "Local", "Proposed") });

      expect(await readAdrsOnRef(repo)).toBeNull();
    });

    it("returns an empty record when main resolves but holds no ADRs", async () => {
      const repo = cloneWhereTheCheckoutIsBehind({ "README.md": "not an adr" }, {});

      expect(await readAdrsOnRef(repo)).toEqual([]);
    });
  },
  GIT_TEST_TIMEOUT_MS
);
